import React, { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'

function AdminDashboard({ role, username = 'Admin' }) {
  const [time, setTime] = useState(new Date())

  useEffect(() => {
    const t = setInterval(() => setTime(new Date()), 1000)
    return () => clearInterval(t)
  }, [])

  const greeting = time.getHours() < 12 ? 'Good morning' : time.getHours() < 18 ? 'Good afternoon' : 'Good evening'

  const cards = [
    { to: '/', icon: '⬛', title: 'Dashboard', desc: 'Overview of all activity and stats' },
    { to: '/employees', icon: '👥', title: 'Employees', desc: 'Browse and manage all employees' },
    { to: '/add-employee/_add', icon: '➕', title: 'Add employee', desc: 'Register a new team member' },
    { to: '/view-leaves', icon: '📅', title: 'View leaves', desc: 'Review and approve leave requests' },
  ]

  return (
    <div style={{ padding: '1.5rem' }}>
      <div>
        <h1 style={{ fontSize: 22, fontWeight: 500 }}>
          {greeting}, {username}
          <span style={{ fontSize: 11, padding: '2px 8px', border: '0.5px solid #ccc', borderRadius: 99, marginLeft: 8, color: '#888' }}>ADMIN</span>
        </h1>
        <p style={{ fontSize: 13, color: '#888', marginTop: 4 }}>
          {time.toLocaleDateString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })} · {time.toLocaleTimeString('en-IN')}
        </p>
      </div>

      <hr style={{ border: 'none', borderTop: '0.5px solid #e0e0e0', margin: '1.25rem 0' }} />

      {role === 'ADMIN' && (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: 12 }}>
          {cards.map(({ to, icon, title, desc }) => (
            <Link key={to} to={to} style={{ textDecoration: 'none' }}>
              <div style={{ background: '#fff', border: '0.5px solid #e0e0e0', borderRadius: 12, padding: '1.25rem', cursor: 'pointer' }}>
                <div style={{ width: 36, height: 36, borderRadius: 8, background: '#f5f5f5', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 16, marginBottom: 10 }}>{icon}</div>
                <div style={{ fontSize: 14, fontWeight: 500, color: '#111' }}>{title}</div>
                <div style={{ fontSize: 12, color: '#888', marginTop: 4, lineHeight: 1.5 }}>{desc}</div>
              </div>
            </Link>
          ))}
        </div>
      )}
    </div>
  )
}

export default AdminDashboard
